-- Name: FUNCTION fn_expert_recherche(p_texte text); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.fn_expert_recherche(p_texte text) IS 'Requête plein texte paramétrée en configuration simple, casse et espaces normalisés ; les mots courants sont reliés par les synonymes explicites de la référence sélectionnée.';


--
-- Name: fn_expert_reference_valide(text, text, integer, integer); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.fn_expert_reference_valide(p_table text, p_champ text, p_valeur integer, p_entite integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM referentiel."T_Generique" g JOIN referentiel."T_CategorieGenerique" c ON c."ID_CategorieGenerique"=g."ID_CategorieGeneriqueFk"
 WHERE g."ID_Generique"=p_valeur AND g."ValideGenerique" AND c."ValideCategorieGenerique" AND referentiel.fn_reference_visible(g."ID_Generique",p_entite)
 AND g."ID_CategorieGeneriqueFk"=ANY(coalesce(referentiel.fn_categories_champ('professionnel',p_table,p_champ,p_entite),ARRAY[]::integer[]))) $$;


--
-- Name: FUNCTION fn_expert_reference_valide(p_table text, p_champ text, p_valeur integer, p_entite integer); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.fn_expert_reference_valide(p_table text, p_champ text, p_valeur integer, p_entite integer) IS 'Contrôle d’une nouvelle sélection : famille configurée du vrai champ, validité de valeur/famille et portée de l’entreprise propriétaire.';


--
-- Name: tr_compte_professionnel_entreprise(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_compte_professionnel_entreprise() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW."IdEntiteFk" IS DISTINCT FROM OLD."IdEntiteFk" AND EXISTS(SELECT FROM professionnel."T_Professionnel" p WHERE p."IdUserFk"=NEW."IdUser" AND p."IdEntiteFk" IS DISTINCT FROM NEW."IdEntiteFk") THEN
  RAISE EXCEPTION 'Ce compte possède une fiche professionnelle rattachée durablement à son entreprise.' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_compte_professionnel_entreprise(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_compte_professionnel_entreprise() IS 'Empêche un déplacement de compte qui contredirait la propriété durable d’une fiche professionnelle existante ; ne change ni authentification ni rôles.';


--
-- Name: tr_detail_professionnel_integrite(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_detail_professionnel_integrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE profile_id integer;owner_id integer;f text;val integer;
BEGIN
 profile_id:=CASE WHEN TG_OP='DELETE' THEN OLD."IdProfessionnelFk" ELSE NEW."IdProfessionnelFk" END;
 SELECT "IdEntiteFk" INTO owner_id FROM professionnel."T_Professionnel" WHERE "IdProfessionnel"=profile_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Fiche professionnelle introuvable.' USING ERRCODE='23503';END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 IF TG_OP='UPDATE' AND NEW."IdProfessionnelFk" IS DISTINCT FROM OLD."IdProfessionnelFk" THEN RAISE EXCEPTION 'Le parent du détail est conservé.' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='T_Professionnel_Entite' THEN
  IF NOT EXISTS(SELECT FROM systeme."T_Entite" WHERE "IdEntite"=NEW."IdEntiteFk" AND "ValideEntite") AND (TG_OP='INSERT' OR NEW."IdEntiteFk" IS DISTINCT FROM OLD."IdEntiteFk") THEN RAISE EXCEPTION 'Structure inactive ou introuvable.' USING ERRCODE='23514';END IF;
  IF (NEW."DateDebut" IS NOT NULL AND NOT isfinite(NEW."DateDebut")) OR (NEW."DateFin" IS NOT NULL AND NOT isfinite(NEW."DateFin")) THEN RAISE EXCEPTION 'Période d’affiliation invalide.' USING ERRCODE='23514';END IF;
  IF NEW."EstPrincipal" THEN
   IF EXISTS(SELECT FROM professionnel."T_Professionnel_Entite" x WHERE x."IdProfessionnelFk"=profile_id AND x."IdEntiteFk"<>NEW."IdEntiteFk" AND x."EstPrincipal" AND tsrange(x."DateDebut",x."DateFin",'[)') && tsrange(NEW."DateDebut",NEW."DateFin",'[)')) THEN RAISE EXCEPTION 'Une seule affiliation principale est possible sur la même période.' USING ERRCODE='23514';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_detail_professionnel_integrite(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_detail_professionnel_integrite() IS 'Sérialise les détails sous le verrou du profil, conserve le parent et contrôle les affiliations principales et dates finies ; ne réattribue aucune entreprise.';


--
-- Name: tr_detail_professionnel_revision(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_detail_professionnel_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE profile_id integer;actor_id integer:=nullif(current_setting('professionnel.actor_id',true),'')::integer;
BEGIN
 IF TG_OP='UPDATE' AND to_jsonb(NEW) IS NOT DISTINCT FROM to_jsonb(OLD) THEN RETURN NULL;END IF;
 profile_id:=CASE WHEN TG_OP='DELETE' THEN OLD."IdProfessionnelFk" ELSE NEW."IdProfessionnelFk" END;
 -- La garde BEFORE du détail a déjà verrouillé ce même parent. Un UPDATE
 -- ordinaire réutilise sa garde, sa révision, son horodatage et son audit.
 -- Sans acteur explicite, le dernier auteur devient inconnu plutôt que
 -- d'attribuer le changement au compte affecté ou à un ancien éditeur.
 IF actor_id IS NOT NULL AND NOT EXISTS(SELECT FROM systeme."T_Utilisateurs" WHERE "IdUser"=actor_id) THEN actor_id:=NULL;END IF;
 UPDATE professionnel."T_Professionnel" SET "ModifieParUserFk"=actor_id WHERE "IdProfessionnel"=profile_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Fiche professionnelle parente introuvable.' USING ERRCODE='23503';END IF;
 RETURN NULL;
END $$;


--
-- Name: FUNCTION tr_detail_professionnel_revision(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_detail_professionnel_revision() IS 'Après un véritable ajout, changement ou retrait de détail, touche le parent sous le verrou existant pour incrémenter sa révision SQL et son horodatage/audit. Une mise à jour sans différence ne change pas sa version. Aucun compte ou propriétaire n’est déduit ; auteur NULL en l’absence de contexte explicite. Tout est annulé avec la transaction en cas de rejet.';


--
-- Name: tr_professionnel_audit(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_professionnel_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE before_row jsonb;after_row jsonb;entity_id integer;profile_id integer;extra jsonb;
BEGIN
 extra:=jsonb_strip_nulls(jsonb_build_object('_requestId',nullif(current_setting('professionnel.request_id',true),''),'_payloadHash',nullif(current_setting('professionnel.payload_hash',true),''),'_actorId',nullif(current_setting('professionnel.actor_id',true),''),'_operation',nullif(current_setting('professionnel.operation',true),''),'_motif',nullif(current_setting('professionnel.motif',true),'')));
 IF TG_OP IN('UPDATE','DELETE') THEN before_row:=systeme.fn_audit_sans_secrets(to_jsonb(OLD))||extra;END IF;
 IF TG_OP IN('INSERT','UPDATE') THEN after_row:=systeme.fn_audit_sans_secrets(to_jsonb(NEW))||extra;END IF;
 IF TG_TABLE_NAME='T_Professionnel' THEN entity_id:=coalesce((after_row->>'IdEntiteFk')::integer,(before_row->>'IdEntiteFk')::integer);
 ELSIF TG_TABLE_NAME='T_SynonymeRecherche' THEN entity_id:=coalesce((after_row->>'IdEntiteFk')::integer,(before_row->>'IdEntiteFk')::integer);
 ELSE profile_id:=coalesce((after_row->>'IdProfessionnelFk')::integer,(before_row->>'IdProfessionnelFk')::integer);SELECT "IdEntiteFk" INTO entity_id FROM professionnel."T_Professionnel" WHERE "IdProfessionnel"=profile_id;END IF;
 INSERT INTO systeme."T_Audit_Log"("TableName","Operation","OldData","NewData","ChangedAt","IdEntiteFk") VALUES(TG_TABLE_SCHEMA||'.'||TG_TABLE_NAME,TG_OP,before_row,after_row,clock_timestamp(),entity_id);
 RETURN NULL;
END $$;


--
-- Name: FUNCTION tr_professionnel_audit(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_professionnel_audit() IS 'Événement SQL unique et transactionnel des fiches, sélections et affiliations ; images sans secrets et métadonnées de rejeu/acteur/motif. Ces métadonnées ne remplacent jamais les permissions serveur.';


--
-- Name: tr_professionnel_integrite(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_professionnel_integrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE account_entity integer;account_global boolean;actor integer:=nullif(current_setting('professionnel.actor_id',true),'')::integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Archivez la fiche pour conserver son historique.' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND (NEW."IdEntiteFk" IS DISTINCT FROM OLD."IdEntiteFk" OR NEW."IdUserFk" IS DISTINCT FROM OLD."IdUserFk" OR NEW."CreeLe" IS DISTINCT FROM OLD."CreeLe" OR NEW."CreeParUserFk" IS DISTINCT FROM OLD."CreeParUserFk" OR NEW."CreationRequestId" IS DISTINCT FROM OLD."CreationRequestId" OR NEW."CreationPayloadHash" IS DISTINCT FROM OLD."CreationPayloadHash") THEN RAISE EXCEPTION 'Propriétaire, compte et identité de création sont conservés.' USING ERRCODE='23514';END IF;
 IF TG_OP='INSERT' THEN
  SELECT "IdEntiteFk",coalesce("Is_Admin",false) INTO account_entity,account_global FROM systeme."T_Utilisateurs" WHERE "IdUser"=NEW."IdUserFk" FOR SHARE;
  IF NOT FOUND OR (account_entity IS DISTINCT FROM NEW."IdEntiteFk" AND NOT(account_entity IS NULL AND account_global AND coalesce(actor=NEW."IdUserFk",false))) THEN RAISE EXCEPTION 'Le compte professionnel appartient à une autre entreprise.' USING ERRCODE='23514';END IF;
  NEW."Revision":=1;NEW."CreeLe":=clock_timestamp();NEW."ModifieLe":=NEW."CreeLe";
 ELSE NEW."Revision":=OLD."Revision"+1;NEW."ModifieLe":=clock_timestamp();END IF;
 IF NEW."Publie" AND (TG_OP='INSERT' OR NOT OLD."Publie") THEN
  IF NOT EXISTS(SELECT FROM systeme."T_Utilisateurs" WHERE "IdUser"=NEW."IdUserFk" AND "ValideUser") OR NOT EXISTS(SELECT FROM systeme."T_Entite" WHERE "IdEntite"=NEW."IdEntiteFk" AND "ValideEntite") OR NOT NEW."ValideProfessionnel" THEN RAISE EXCEPTION 'Seule une fiche active d’un compte et d’une entreprise actifs peut être publiée.' USING ERRCODE='23514';END IF;
  IF NOT professionnel.fn_expert_reference_valide('T_Professionnel','IdTypeProfessionnelFk',NEW."IdTypeProfessionnelFk",NEW."IdEntiteFk") OR NOT professionnel.fn_expert_reference_valide('T_Professionnel','IdSecteurFk',NEW."IdSecteurFk",NEW."IdEntiteFk") OR (NEW."IdSpecialiteFk" IS NOT NULL AND NOT professionnel.fn_expert_reference_valide('T_Professionnel','IdSpecialiteFk',NEW."IdSpecialiteFk",NEW."IdEntiteFk")) THEN RAISE EXCEPTION 'Corrigez les références devenues incompatibles avant de publier.' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_professionnel_integrite(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_professionnel_integrite() IS 'Propriété et compte immuables, révision SQL, cohérence initiale compte/entreprise et publication explicite. Exception limitée au compte global qui se représente lui-même dans une entreprise choisie ; la GUC n’accorde aucun droit API.';


--
-- Name: tr_synonyme_portee(); Type: FUNCTION; Schema: professionnel; Owner: -
--

CREATE FUNCTION professionnel.tr_synonyme_portee() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_id integer;
BEGIN
 SELECT "IdEntiteFk" INTO owner_id FROM referentiel."T_Generique" WHERE "ID_Generique"=NEW."IdGeneriqueFk" FOR SHARE;
 IF NOT FOUND OR NEW."IdEntiteFk" IS DISTINCT FROM owner_id THEN RAISE EXCEPTION 'La portée du synonyme doit être celle de sa référence.' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_synonyme_portee(); Type: COMMENT; Schema: professionnel; Owner: -
--

COMMENT ON FUNCTION professionnel.tr_synonyme_portee() IS 'Un terme de recherche hérite exactement de la portée de sa valeur centrale, sans exposer les dictionnaires d’une autre entreprise.';


--
-- Name: fn_catalogue_tableau_verifier(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_catalogue_tableau_verifier() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE c jsonb; ids text[]:='{}';
BEGIN
 IF jsonb_array_length(NEW."Colonnes") NOT BETWEEN 1 AND 100 THEN
  RAISE EXCEPTION 'Catalogue de colonnes invalide' USING ERRCODE='23514';
 END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(NEW."Colonnes") LOOP
  IF jsonb_typeof(c)<>'object' OR c->>'id' IS NULL OR c->>'id' !~ '^[A-Za-z][A-Za-z0-9_]*$'
   OR c->>'label' IS NULL OR nullif(btrim(c->>'label'),'') IS NULL
   OR jsonb_typeof(c->'defaultVisible') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(c->'defaultExport') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(c->'exportable') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(c->'defaultOrder') IS DISTINCT FROM 'number'
   OR c->>'type' IS NULL OR c->>'id'=ANY(ids)
   OR (c->>'defaultExport'='true' AND c->>'exportable'<>'true')
   OR (c->>'id'='actions' AND c->>'exportable'<>'false') THEN
    RAISE EXCEPTION 'Définition de colonne invalide ou dupliquée' USING ERRCODE='23514';
  END IF;
  ids:=array_append(ids,c->>'id');
 END LOOP;
 IF TG_OP='UPDATE' THEN
  IF NEW."CleInterface" IS DISTINCT FROM OLD."CleInterface" OR NEW."Module" IS DISTINCT FROM OLD."Module" THEN
   RAISE EXCEPTION 'Identité du catalogue immuable' USING ERRCODE='23514';
  END IF;
  NEW."Version":=OLD."Version"+1;
 END IF;
 NEW."ModifieLe":=clock_timestamp();
 RETURN NEW;
END $_$;


--
-- Name: FUNCTION fn_catalogue_tableau_verifier(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_catalogue_tableau_verifier() IS 'Vérifie les identifiants, options et doublons du catalogue ; interdit l’export des actions et versionne ses modifications.';


--
-- Name: fn_categorie_visible(integer, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_categorie_visible(p_categorie integer, p_entite integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM referentiel."T_CategorieGenerique" c WHERE c."ID_CategorieGenerique"=p_categorie
  AND (c."IdEntiteFk" IS NULL OR c."IdEntiteFk"=p_entite)) $$;


--
-- Name: FUNCTION fn_categorie_visible(p_categorie integer, p_entite integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_categorie_visible(p_categorie integer, p_entite integer) IS 'Visibilité de portée uniquement : catégorie commune ou de l’entreprise explicitement indiquée, jamais d’une autre. NULL entreprise ne désigne que les catégories communes ; validité contrôlée séparément.';


--
-- Name: fn_categories_champ(text, text, text, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_categories_champ(p_schema text, p_table text, p_colonne text, p_entite integer DEFAULT NULL::integer) RETURNS integer[]
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$ SELECT "CategoryIds" FROM referentiel.fn_resolution_champ(p_schema,p_table,p_colonne,p_entite) $$;


--
-- Name: FUNCTION fn_categories_champ(p_schema text, p_table text, p_colonne text, p_entite integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_categories_champ(p_schema text, p_table text, p_colonne text, p_entite integer) IS 'Familles effectives du champ physique et de son entreprise. Vide signifie non configuré ; les scopes pays et visibilités historiques ne sont pas implicitement activés.';


--
-- Name: fn_entite_reference_champ(text, text, jsonb); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_entite_reference_champ(p_schema text, p_table text, p_ligne jsonb) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner_id integer;
BEGIN
 IF p_ligne IS NULL OR NOT EXISTS(SELECT FROM referentiel."T_ChampReferentiel" WHERE "SchemaName"=p_schema AND "TableName"=p_table AND "SupportsEntityScope") THEN RETURN NULL;END IF;
 IF p_schema='professionnel' AND p_table IN('T_Professionnel_Competence','T_Professionnel_Prestation','T_Professionnel_Entite') THEN
  SELECT "IdEntiteFk" INTO owner_id FROM professionnel."T_Professionnel" WHERE "IdProfessionnel"=nullif(p_ligne->>'IdProfessionnelFk','')::integer;RETURN owner_id;END IF;
 IF (p_schema,p_table)=('logistique','T_PrecisionStock') THEN
  SELECT "IdEntiteFk" INTO owner_id FROM referentiel."T_Generique" WHERE "ID_Generique"=nullif(p_ligne->>'ID_UniteFk','')::integer;RETURN owner_id;END IF;
 IF (p_schema,p_table)=('systeme','T_Entite') THEN RETURN nullif(p_ligne->>'IdEntite','')::integer;END IF;
 owner_id:=coalesce(nullif(p_ligne->>'IdEntiteFk','')::integer,nullif(p_ligne->>'ID_EntiteFk','')::integer);
 IF owner_id IS NOT NULL THEN RETURN owner_id;END IF;
 IF p_schema='support' AND p_table='T_ResolutionSupport' THEN
  SELECT "IdEntiteFk" INTO owner_id FROM support."T_Support" WHERE "ID_Support"=nullif(p_ligne->>'ID_SupportFk','')::bigint;RETURN owner_id;END IF;
 IF p_schema='logistique' THEN CASE p_table
  WHEN 'T_Mouvement' THEN SELECT "IdEntiteFk" INTO owner_id FROM logistique."T_Commande" WHERE "ID_Commande"=nullif(p_ligne->>'ID_cmdFk','')::integer;
   IF owner_id IS NULL THEN SELECT "IdEntiteFk" INTO owner_id FROM logistique."T_Article" WHERE "ID_Article"=nullif(p_ligne->>'ID_ArticleFk','')::integer;END IF;
  WHEN 'T_Reglements' THEN SELECT "IdEntiteFk" INTO owner_id FROM logistique."T_Facture" WHERE "CodeFacture"=p_ligne->>'CodeFactureFk';
   IF owner_id IS NULL THEN SELECT "IdEntiteFk" INTO owner_id FROM logistique."T_Commande" WHERE "CodeFacture"=p_ligne->>'CodeFactureFk';END IF;
  WHEN 'T_Remboursement' THEN SELECT "IdEntiteFk" INTO owner_id FROM logistique."T_Avoir" WHERE "ID_Avoir"=nullif(p_ligne->>'ID_AvoirFk','')::bigint;
  ELSE NULL;END CASE;END IF;
 RETURN owner_id;
END $$;


--
-- Name: FUNCTION fn_entite_reference_champ(p_schema text, p_table text, p_ligne jsonb); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_entite_reference_champ(p_schema text, p_table text, p_ligne jsonb) IS 'Contexte durable des références : propriétaire explicite, ou parent métier prouvé ; compétences, prestations et affiliations prennent l’entreprise de leur fiche. La structure affiliée n’est pas le propriétaire. Ne prend jamais l’entreprise courante du compte représenté.';


--
-- Name: fn_guard_sens_stock(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_guard_sens_stock() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF EXISTS(SELECT FROM logistique."T_Commande" WHERE "ID_TypeCmdFk"=OLD."ID_Generique") OR EXISTS(SELECT FROM logistique."T_Mouvement" WHERE "ID_TypeMvtFk"=OLD."ID_Generique") THEN
  IF NEW."ID_CategorieGeneriqueFk" IS DISTINCT FROM OLD."ID_CategorieGeneriqueFk" OR logistique.fn_nature_type_bon(NEW."AbrGenerique") IS DISTINCT FROM logistique.fn_nature_type_bon(OLD."AbrGenerique") THEN
   RAISE EXCEPTION 'La nature d’un type de bon déjà utilisé ne peut pas changer.' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_guard_sens_stock(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_guard_sens_stock() IS 'Conserve le sens des types de bon déjà utilisés, dans toute famille actuelle ou ancienne, sans dépendre de l’identifiant historique64.';


--
-- Name: fn_normaliser_libelle(text); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_normaliser_libelle(p_texte text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT lower(btrim(regexp_replace(p_texte,'[[:space:]'||chr(160)||']+',' ','g'))) $$;


--
-- Name: FUNCTION fn_normaliser_libelle(p_texte text); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_normaliser_libelle(p_texte text) IS 'Clé de comparaison des libellés/codes : casse et espaces normalisés, y compris espace insécable. Les accents restent distincts ; la forme affichée et les identifiants ne sont jamais réécrits.';


--
-- Name: fn_preference_tableau_verifier(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_preference_tableau_verifier() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE c jsonb; id text; ids text[]:='{}'; defs jsonb; auteur integer; usr record;
BEGIN
 auteur:=systeme.fn_admin_actor_user_id();
 IF auteur IS NULL OR auteur IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN OLD."IdUserFk" ELSE NEW."IdUserFk" END) THEN
  RAISE EXCEPTION 'Auteur de préférence non autorisé' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 SELECT "Is_Admin","IdEntiteFk" INTO usr FROM systeme."T_Utilisateurs" WHERE "IdUser"=auteur;
 IF usr."Is_Admin" IS NOT TRUE AND (NEW."IdEntiteFk" IS NULL OR NEW."IdEntiteFk" IS DISTINCT FROM usr."IdEntiteFk") THEN
  RAISE EXCEPTION 'Préférence hors entreprise autorisée' USING ERRCODE='23514';
 END IF;
 SELECT "Colonnes" INTO defs FROM referentiel."T_InterfaceTableau" WHERE "CleInterface"=NEW."CleInterfaceFk" AND "Actif";
 IF defs IS NULL OR jsonb_array_length(NEW."Colonnes") NOT BETWEEN 1 AND 100 THEN
  RAISE EXCEPTION 'Colonnes de préférence invalides' USING ERRCODE='23514';
 END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(NEW."Colonnes") LOOP
  id:=c#>>'{}';
  IF jsonb_typeof(c)<>'string' OR id=ANY(ids) OR NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(defs) d WHERE d->>'id'=id
      AND (CASE WHEN NEW."Usage"='export' THEN d->>'exportable'='true' ELSE coalesce(d->>'tableAvailable','true')='true' END)) THEN
   RAISE EXCEPTION 'Colonne inconnue, non exportable ou dupliquée' USING ERRCODE='23514';
  END IF;
  ids:=array_append(ids,id);
 END LOOP;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW."CleInterfaceFk",NEW."IdUserFk",NEW."IdEntiteFk",NEW."Usage") IS DISTINCT FROM
     ROW(OLD."CleInterfaceFk",OLD."IdUserFk",OLD."IdEntiteFk",OLD."Usage") THEN
   RAISE EXCEPTION 'Propriétaire et usage de préférence immuables' USING ERRCODE='23514';
  END IF;
 END IF;
 NEW."Version":=nextval('referentiel.seq_preference_tableau_revision');
 NEW."ModifieLe":=clock_timestamp();
 RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_preference_tableau_verifier(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_preference_tableau_verifier() IS 'Contrôle SQL de l’auteur et entreprise, des colonnes autorisées et de l’indépendance tableau/export ; date et révise les modifications.';


--
-- Name: fn_reference_champ_connue(text, text, text, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_reference_champ_connue(p_schema text, p_table text, p_colonne text, p_valeur integer) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r referentiel."T_ChampReferentiel"; cat integer; used boolean;
BEGIN
 IF p_valeur IS NULL THEN RETURN true;END IF;
 SELECT * INTO r FROM referentiel."T_ChampReferentiel" WHERE "SchemaName"=p_schema AND "TableName"=p_table AND "ColumnName"=p_colonne;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT "ID_CategorieGeneriqueFk" INTO cat FROM referentiel."T_Generique" WHERE "ID_Generique"=p_valeur;
 IF NOT FOUND THEN RETURN false;END IF;
 IF cat=r."ID_CategorieDefautFk" OR (r."CanConfigure" AND EXISTS(SELECT FROM systeme."T_Fk_Correspondance" f
 WHERE f."MappingType"='generic_category' AND f."TargetCategoryIdFk"=cat AND (f."IdChampReferentielFk"=r."ID_ChampReferentiel" OR (f."IdChampReferentielFk" IS NULL AND f."SourceKey"=ANY(r."AliasSourceKeys"))))) THEN RETURN true;END IF;
 EXECUTE format('SELECT EXISTS(SELECT FROM %I.%I WHERE %I=$1)',p_schema,p_table,p_colonne) INTO used USING p_valeur;
 RETURN used;
END $_$;


--
-- Name: FUNCTION fn_reference_champ_connue(p_schema text, p_table text, p_colonne text, p_valeur integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_reference_champ_connue(p_schema text, p_table text, p_colonne text, p_valeur integer) IS 'Reconnaissance de lecture et des procédures historiques : famille de référence, catégorie déclarée ou valeur déjà utilisée dans la vraie FK. Ne remplace jamais la validation stricte d’une nouvelle affectation.';


--
-- Name: fn_reference_visible(integer, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_reference_visible(p_valeur integer, p_entite integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM referentiel."T_Generique" g WHERE g."ID_Generique"=p_valeur
  AND (g."IdEntiteFk" IS NULL OR g."IdEntiteFk"=p_entite)
  AND referentiel.fn_categorie_visible(g."ID_CategorieGeneriqueFk",p_entite)) $$;


--
-- Name: FUNCTION fn_reference_visible(p_valeur integer, p_entite integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_reference_visible(p_valeur integer, p_entite integer) IS 'Visibilité d’une valeur et de sa famille dans le même périmètre commun/entreprise, sans autorisation d’accès supplémentaire. Ne confond ni valeur inactive ni référence hors catégorie avec une autre entreprise.';


--
-- Name: fn_resolution_champ(text, text, text, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_resolution_champ(p_schema text, p_table text, p_colonne text, p_entite integer DEFAULT NULL::integer) RETURNS TABLE("CategoryIds" integer[], "OrigineReglage" text)
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 WITH champ AS (SELECT * FROM referentiel."T_ChampReferentiel" WHERE "SchemaName"=p_schema AND "TableName"=p_table AND "ColumnName"=p_colonne),
 candidates AS (
 SELECT f.*,CASE WHEN f."SettingScope"='entity' THEN CASE WHEN f."IdChampReferentielFk" IS NOT NULL THEN 1 ELSE 2 END ELSE CASE WHEN f."IdChampReferentielFk" IS NOT NULL THEN 3 ELSE 4 END END priority
 FROM champ c JOIN systeme."T_Fk_Correspondance" f ON (f."IdChampReferentielFk"=c."ID_ChampReferentiel" OR (f."IdChampReferentielFk" IS NULL AND f."SourceKey"=ANY(c."AliasSourceKeys")))
 WHERE c."CanConfigure" AND f."MappingType"='generic_category' AND f."ValideFkCorrespondance"
 AND ((f."SettingScope"='global' AND f."ScopeValue" IS NULL) OR (c."SupportsEntityScope" AND f."SettingScope"='entity' AND f."ScopeValue"=p_entite::text))
 ), chosen AS (SELECT * FROM candidates WHERE priority=(SELECT min(priority) FROM candidates)),
 resolved AS (SELECT CASE WHEN EXISTS(SELECT FROM chosen) THEN
 CASE WHEN EXISTS(SELECT FROM chosen WHERE "MappingValue"='@default') THEN ARRAY_REMOVE(ARRAY[c."ID_CategorieDefautFk"],NULL)
 ELSE ARRAY(SELECT DISTINCT "TargetCategoryIdFk" FROM chosen WHERE "TargetCategoryIdFk" IS NOT NULL ORDER BY "TargetCategoryIdFk") END
 ELSE ARRAY_REMOVE(ARRAY[c."ID_CategorieDefautFk"],NULL) END ids,
 CASE WHEN EXISTS(SELECT FROM chosen WHERE "MappingValue"='@default') THEN CASE WHEN c."ID_CategorieDefautFk" IS NULL THEN 'non_configure' ELSE 'defaut' END
 WHEN EXISTS(SELECT FROM chosen WHERE "SettingScope"='entity') THEN 'entity'
 WHEN EXISTS(SELECT FROM chosen) THEN 'global'
 WHEN c."ID_CategorieDefautFk" IS NULL THEN 'non_configure' ELSE 'defaut' END origin FROM champ c)
 SELECT coalesce((SELECT ids FROM resolved),'{}'::integer[]),coalesce((SELECT origin FROM resolved),'inconnu') $$;


--
-- Name: FUNCTION fn_resolution_champ(p_schema text, p_table text, p_colonne text, p_entite integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_resolution_champ(p_schema text, p_table text, p_colonne text, p_entite integer) IS 'Résolution canonique : entreprise puis global, jeu canonique avant alias au même scope, puis défaut immuable. Un marqueur explicite @default ne retombe jamais sur une ancienne surcharge.';


--
-- Name: fn_valider_reference_champ(text, text, text, integer, integer); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.fn_valider_reference_champ(p_schema text, p_table text, p_colonne text, p_valeur integer, p_entite integer DEFAULT NULL::integer) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT p_valeur IS NULL OR EXISTS(SELECT FROM referentiel."T_Generique" g JOIN referentiel."T_CategorieGenerique" c ON c."ID_CategorieGenerique"=g."ID_CategorieGeneriqueFk"
  JOIN referentiel."T_ChampReferentiel" r ON r."SchemaName"=p_schema AND r."TableName"=p_table AND r."ColumnName"=p_colonne
  WHERE g."ID_Generique"=p_valeur AND g."ValideGenerique" AND c."ValideCategorieGenerique"
   AND g."ID_CategorieGeneriqueFk"=ANY(referentiel.fn_categories_champ(p_schema,p_table,p_colonne,p_entite))
   AND referentiel.fn_reference_visible(p_valeur,CASE WHEN r."SupportsEntityScope" THEN p_entite END)) $$;


--
-- Name: FUNCTION fn_valider_reference_champ(p_schema text, p_table text, p_colonne text, p_valeur integer, p_entite integer); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.fn_valider_reference_champ(p_schema text, p_table text, p_colonne text, p_valeur integer, p_entite integer) IS 'Nouvelle sélection active de la catégorie configurée et de la portée propriétaire réelle. Les champs communs excluent toutes les valeurs privées ; les références historiques inchangées restent gérées par la garde physique existante.';


--
-- Name: tr_catalogue_champ_integrite(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.tr_catalogue_champ_integrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Catalogue physique conservé.' USING ERRCODE='23514';END IF;
 IF TG_OP='INSERT' THEN
  IF NOT EXISTS(SELECT FROM pg_constraint k JOIN pg_class t ON t.oid=k.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace
   JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum=ANY(k.conkey) WHERE k.contype='f' AND k.confrelid='referentiel."T_Generique"'::regclass
   AND n.nspname=NEW."SchemaName" AND t.relname=NEW."TableName" AND a.attname=NEW."ColumnName") THEN RAISE EXCEPTION 'Colonne physique à FK non prouvée.' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;
 IF (to_jsonb(NEW)-ARRAY['Revision','ModifieLe','ModifieParUserFk']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['Revision','ModifieLe','ModifieParUserFk']) OR pg_trigger_depth()<2 THEN
  RAISE EXCEPTION 'Définition et catégorie de référence immuables ; utilisez les correspondances courantes.' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_catalogue_champ_integrite(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.tr_catalogue_champ_integrite() IS 'Conserve la clé physique, le défaut prouvé et la politique de sécurité ; seule une révision interne issue des correspondances peut modifier les métadonnées. Un chargement initial doit prouver la vraie FK ; les clés déjà installées sont uniques.';


--
-- Name: tr_categorie_portee_doublon(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.tr_categorie_portee_doublon() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE normalise text; duplicate_id integer;
BEGIN
 IF TG_OP='UPDATE' AND NEW."IdEntiteFk" IS DISTINCT FROM OLD."IdEntiteFk" THEN
  RAISE EXCEPTION 'La portée d’une catégorie enregistrée est conservée.' USING ERRCODE='23514',CONSTRAINT='ck_categorie_portee_immuable';END IF;
 normalise:=referentiel.fn_normaliser_libelle(NEW."NomCategorieGenerique");
 IF TG_OP='UPDATE' AND normalise IS NOT DISTINCT FROM referentiel.fn_normaliser_libelle(OLD."NomCategorieGenerique") THEN RETURN NEW;END IF;
 IF coalesce(normalise,'')='' THEN RAISE EXCEPTION 'Indiquez le libellé de la catégorie.' USING ERRCODE='23514',CONSTRAINT='ck_categorie_nom_requis';END IF;
 -- Un verrou commun sérialise les lots de catégories dans un ordre unique.
 PERFORM pg_advisory_xact_lock(hashtextextended('referentiel:categories:identite',0));
 SELECT "ID_CategorieGenerique" INTO duplicate_id FROM referentiel."T_CategorieGenerique" c
  WHERE c."ID_CategorieGenerique"<>NEW."ID_CategorieGenerique"
   AND referentiel.fn_normaliser_libelle(c."NomCategorieGenerique")=normalise
   AND (NEW."IdEntiteFk" IS NULL OR c."IdEntiteFk" IS NULL OR c."IdEntiteFk"=NEW."IdEntiteFk") LIMIT 1;
 IF FOUND THEN RAISE EXCEPTION 'Une catégorie de même nom existe déjà dans cette portée.' USING ERRCODE='23505',CONSTRAINT='uq_categorie_nom_effectif';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_categorie_portee_doublon(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.tr_categorie_portee_doublon() IS 'Propriété immuable et noms non vides non ambigus entre commun et entreprise. Les identités historiques inchangées restent modifiables descriptivement ; le verrou transactionnel interdit les doublons concurrents.';


--
-- Name: tr_generique_portee_doublon(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.tr_generique_portee_doublon() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE famille_entite integer; nom text; code text; nom_change boolean; code_change boolean;
BEGIN
 IF TG_OP='UPDATE' AND NEW."IdEntiteFk" IS DISTINCT FROM OLD."IdEntiteFk" THEN
  RAISE EXCEPTION 'La portée d’une valeur enregistrée est conservée.' USING ERRCODE='23514',CONSTRAINT='ck_generique_portee_immuable';END IF;
 SELECT "IdEntiteFk" INTO famille_entite FROM referentiel."T_CategorieGenerique" WHERE "ID_CategorieGenerique"=NEW."ID_CategorieGeneriqueFk" FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Catégorie introuvable.' USING ERRCODE='23503';END IF;
 IF famille_entite IS NOT NULL AND NEW."IdEntiteFk" IS DISTINCT FROM famille_entite THEN
  RAISE EXCEPTION 'Une valeur de catégorie privée appartient à la même entreprise.' USING ERRCODE='23514',CONSTRAINT='ck_generique_categorie_portee';END IF;
 IF NEW."IdEntiteFk" IS NOT NULL AND EXISTS(SELECT FROM referentiel."T_ChampReferentiel" r
  WHERE NOT r."CanConfigure" AND r."ID_CategorieDefautFk"=NEW."ID_CategorieGeneriqueFk") THEN
  RAISE EXCEPTION 'Les valeurs d’une famille de sécurité restent communes.' USING ERRCODE='23514',CONSTRAINT='ck_generique_securite_commune';END IF;
 nom:=referentiel.fn_normaliser_libelle(NEW."NomGenerique");code:=referentiel.fn_normaliser_libelle(NEW."AbrGenerique");
 nom_change:=TG_OP='INSERT';code_change:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN
  nom_change:=nom IS DISTINCT FROM referentiel.fn_normaliser_libelle(OLD."NomGenerique") OR NEW."ID_CategorieGeneriqueFk" IS DISTINCT FROM OLD."ID_CategorieGeneriqueFk";
  code_change:=code IS DISTINCT FROM referentiel.fn_normaliser_libelle(OLD."AbrGenerique") OR NEW."ID_CategorieGeneriqueFk" IS DISTINCT FROM OLD."ID_CategorieGeneriqueFk";
 END IF;
 IF NOT(nom_change OR code_change) THEN RETURN NEW;END IF;
 IF nom_change AND coalesce(nom,'')='' THEN RAISE EXCEPTION 'Indiquez le libellé de la valeur.' USING ERRCODE='23514',CONSTRAINT='ck_generique_nom_requis';END IF;
 -- Une famille est commune au lot de valeurs, comme l’en-tête d’un bon.
 PERFORM pg_advisory_xact_lock(hashtextextended('referentiel:valeurs:'||NEW."ID_CategorieGeneriqueFk"::text,0));
 IF nom_change AND EXISTS(SELECT FROM referentiel."T_Generique" g WHERE g."ID_Generique"<>NEW."ID_Generique" AND g."ID_CategorieGeneriqueFk"=NEW."ID_CategorieGeneriqueFk"
  AND referentiel.fn_normaliser_libelle(g."NomGenerique")=nom AND (NEW."IdEntiteFk" IS NULL OR g."IdEntiteFk" IS NULL OR g."IdEntiteFk"=NEW."IdEntiteFk")) THEN
  RAISE EXCEPTION 'Un libellé identique existe déjà dans cette catégorie et cette portée.' USING ERRCODE='23505',CONSTRAINT='uq_generique_nom_effectif';END IF;
 IF code_change AND coalesce(code,'')<>'' AND EXISTS(SELECT FROM referentiel."T_Generique" g WHERE g."ID_Generique"<>NEW."ID_Generique" AND g."ID_CategorieGeneriqueFk"=NEW."ID_CategorieGeneriqueFk"
  AND referentiel.fn_normaliser_libelle(g."AbrGenerique")=code AND (NEW."IdEntiteFk" IS NULL OR g."IdEntiteFk" IS NULL OR g."IdEntiteFk"=NEW."IdEntiteFk")) THEN
  RAISE EXCEPTION 'Un code identique existe déjà dans cette catégorie et cette portée.' USING ERRCODE='23505',CONSTRAINT='uq_generique_code_effectif';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_generique_portee_doublon(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.tr_generique_portee_doublon() IS 'Cohérence de propriétaire catégorie/valeur et contrôle des nouveaux libellés/codes, sérialisé par famille. Les familles de sécurité non configurables restent communes. Un doublon privé entre entreprises distinctes reste autorisé ; aucun ancien doublon n’est fusionné ou effacé.';


--
-- Name: tr_reference_utilisee_integrite(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.tr_reference_utilisee_integrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r record; used boolean;
BEGIN
 IF TG_OP='UPDATE' AND NEW."ID_Generique" IS NOT DISTINCT FROM OLD."ID_Generique" AND NEW."ID_CategorieGeneriqueFk" IS NOT DISTINCT FROM OLD."ID_CategorieGeneriqueFk" THEN RETURN NEW;END IF;
 FOR r IN SELECT "SchemaName" s,"TableName" t,"ColumnName" col FROM referentiel."T_ChampReferentiel" LOOP
  EXECUTE format('SELECT EXISTS(SELECT FROM %I.%I WHERE %I=$1)',r.s,r.t,r.col) INTO used USING OLD."ID_Generique";
  IF used THEN RAISE EXCEPTION 'Identité et famille d’une référence utilisée sont conservées ; désactivez-la si nécessaire.' USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $_$;


--
-- Name: FUNCTION tr_reference_utilisee_integrite(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.tr_reference_utilisee_integrite() IS 'Empêche une suppression/cascade ou migration de famille d’une valeur déjà utilisée dans les FK physiques, afin de préserver les historiques. Désactivation et changement de libellé restent distincts.';


--
-- Name: tr_valider_champ_referentiel(); Type: FUNCTION; Schema: referentiel; Owner: -
--

CREATE FUNCTION referentiel.tr_valider_champ_referentiel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record; before_data jsonb; after_data jsonb:=to_jsonb(NEW); owner_id integer; old_owner integer; value_id integer; parent_data jsonb; parent_column text;
BEGIN
 IF TG_OP='UPDATE' THEN before_data:=to_jsonb(OLD);END IF;
 owner_id:=referentiel.fn_entite_reference_champ(TG_TABLE_SCHEMA,TG_TABLE_NAME,after_data);
 old_owner:=referentiel.fn_entite_reference_champ(TG_TABLE_SCHEMA,TG_TABLE_NAME,before_data);
 IF TG_TABLE_SCHEMA='logistique' THEN
  IF TG_TABLE_NAME='T_Mouvement' THEN
   SELECT to_jsonb(c) INTO parent_data FROM logistique."T_Commande" c WHERE c."ID_Commande"=(after_data->>'ID_cmdFk')::integer;
   IF parent_data IS NULL THEN SELECT to_jsonb(a) INTO parent_data FROM logistique."T_Article" a WHERE a."ID_Article"=(after_data->>'ID_ArticleFk')::integer;END IF;
  ELSIF TG_TABLE_NAME IN('T_Facture','T_Avoir') THEN SELECT to_jsonb(c) INTO parent_data FROM logistique."T_Commande" c WHERE c."ID_Commande"=(after_data->>'ID_CommandeFk')::integer;
  ELSIF TG_TABLE_NAME='T_Reglements' THEN SELECT to_jsonb(c) INTO parent_data FROM logistique."T_Facture" c WHERE c."CodeFacture"=after_data->>'CodeFactureFk';
  ELSIF TG_TABLE_NAME='T_Remboursement' THEN SELECT to_jsonb(c) INTO parent_data FROM logistique."T_Avoir" c WHERE c."ID_Avoir"=(after_data->>'ID_AvoirFk')::bigint;
  ELSIF TG_TABLE_NAME='T_ValorisationOuverture' THEN SELECT to_jsonb(a) INTO parent_data FROM logistique."T_Article" a WHERE a."ID_Article"=(after_data->>'ID_ArticleFk')::integer;
  END IF;
 END IF;
 FOR r IN SELECT * FROM referentiel."T_ChampReferentiel" WHERE "SchemaName"=TG_TABLE_SCHEMA AND "TableName"=TG_TABLE_NAME ORDER BY "ID_ChampReferentiel" LOOP
  IF TG_OP='UPDATE' AND after_data->r."ColumnName" IS NOT DISTINCT FROM before_data->r."ColumnName" AND owner_id IS NOT DISTINCT FROM old_owner THEN CONTINUE;END IF;
  value_id:=nullif(after_data->>r."ColumnName",'')::integer;
  IF value_id IS NOT NULL THEN PERFORM 1 FROM referentiel."T_Generique" WHERE "ID_Generique"=value_id FOR SHARE;END IF;
  -- Une référence financière/physique copiée exactement du parent historique
  -- reste celle du parent, même après changement de la catégorie proposée.
  parent_column:=CASE WHEN TG_TABLE_NAME='T_Mouvement' AND r."ColumnName"='ID_TypeMvtFk' THEN 'ID_TypeCmdFk' ELSE r."ColumnName" END;
  IF TG_TABLE_SCHEMA='logistique' AND parent_data IS NOT NULL AND (
   r."ColumnName"='ID_DeviseFk' OR (TG_TABLE_NAME='T_Mouvement' AND r."ColumnName"='ID_TypeMvtFk')
   OR (TG_TABLE_NAME='T_Facture' AND r."ColumnName" IN('ID_ModePaiementFk','ID_ConditionPaiementFk')))
   AND owner_id IS NOT DISTINCT FROM (parent_data->>'IdEntiteFk')::integer
   AND value_id IS NOT NULL AND after_data->r."ColumnName" IS NOT DISTINCT FROM parent_data->parent_column THEN CONTINUE;END IF;
  IF NOT referentiel.fn_valider_reference_champ(TG_TABLE_SCHEMA,TG_TABLE_NAME,r."ColumnName",value_id,owner_id) THEN
   RAISE EXCEPTION 'Référence inactive ou incompatible pour %.%.%.',TG_TABLE_SCHEMA,TG_TABLE_NAME,r."ColumnName" USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_valider_champ_referentiel(); Type: COMMENT; Schema: referentiel; Owner: -
--

COMMENT ON FUNCTION referentiel.tr_valider_champ_referentiel() IS 'Garde de toutes les FK cataloguées : INSERT ou changement effectif de valeur/entreprise seulement. Une référence historique inchangée reste consultable et autorise une modification descriptive.';


--
-- Name: fn_etat_support(jsonb, integer); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.fn_etat_support(p_circuit jsonb, p_statut integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$SELECT key FROM jsonb_each_text(p_circuit->'states') WHERE value=p_statut::text LIMIT 1$$;


--
-- Name: FUNCTION fn_etat_support(p_circuit jsonb, p_statut integer); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.fn_etat_support(p_circuit jsonb, p_statut integer) IS 'Rôle sémantique d’un statut dans la copie exacte du circuit du dossier ; aucun libellé ni ID de catégorie dupliqué.';


--
-- Name: tr_enfant_support_verifier(); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.tr_enfant_support_verifier() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE actor integer:=systeme.fn_admin_actor_user_id();parent support."T_Support";state text;piece logistique."T_PieceJustificative";entity_id integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Les échanges, résolutions et preuves du dossier sont conservés.' USING ERRCODE='23514';END IF;
 SELECT * INTO parent FROM support."T_Support" WHERE "ID_Support"=NEW."ID_SupportFk" FOR UPDATE;
 IF NOT FOUND OR parent."Archive" THEN RAISE EXCEPTION 'Dossier inexistant ou archivé.' USING ERRCODE='23514';END IF;
 state:=support.fn_etat_support(parent."CircuitSnapshot",parent."ID_StatutFk");
 IF actor IS NULL OR NOT EXISTS(SELECT FROM systeme."T_Utilisateurs" WHERE "IdUser"=actor AND ("Is_Admin" OR "IdEntiteFk"=parent."IdEntiteFk")) THEN RAISE EXCEPTION 'Auteur hors entreprise du dossier.' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='T_CommentaireSupport' THEN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Les commentaires sont conservés sans réécriture.' USING ERRCODE='23514';END IF;
  IF state='closed' THEN RAISE EXCEPTION 'Rouvrez le dossier avant de commenter.' USING ERRCODE='23514';END IF;
  NEW."ID_AuteurFk":=actor;NEW."DateCreation":=clock_timestamp();NEW."DateModification":=NEW."DateCreation";
 ELSIF TG_TABLE_NAME='T_ResolutionSupport' THEN
  IF TG_OP='INSERT' THEN
   IF state NOT IN('active','pending') OR parent."ID_ResponsableFk" IS NULL THEN RAISE EXCEPTION 'Le dossier doit être pris en charge avant proposition de solution.' USING ERRCODE='23514';END IF;
   IF NEW."ID_ResultatVerificationFk" IS NOT NULL OR NEW."ID_VerifieParFk" IS NOT NULL OR NEW."DateVerification" IS NOT NULL THEN RAISE EXCEPTION 'La vérification intervient après la proposition.' USING ERRCODE='23514';END IF;
   NEW."ID_ProposeParFk":=actor;NEW."DateProposition":=clock_timestamp();
  ELSE
   IF ROW(NEW."ID_ResolutionSupport",NEW."ID_SupportFk",NEW."CauseIdentifiee",NEW."SolutionAppliquee",NEW."ID_ProposeParFk",NEW."DateProposition") IS DISTINCT FROM ROW(OLD."ID_ResolutionSupport",OLD."ID_SupportFk",OLD."CauseIdentifiee",OLD."SolutionAppliquee",OLD."ID_ProposeParFk",OLD."DateProposition") OR OLD."ID_ResultatVerificationFk" IS NOT NULL THEN RAISE EXCEPTION 'La tentative et sa vérification sont immuables ; créez une nouvelle tentative.' USING ERRCODE='23514';END IF;
   IF state<>'resolved' OR NEW."ID_ResolutionSupport" IS DISTINCT FROM (SELECT max("ID_ResolutionSupport") FROM support."T_ResolutionSupport" WHERE "ID_SupportFk"=parent."ID_Support") THEN RAISE EXCEPTION 'Seule la dernière résolution en attente peut être vérifiée.' USING ERRCODE='23514';END IF;
   IF actor=NEW."ID_ProposeParFk" THEN RAISE EXCEPTION 'La vérification doit être faite par une autre personne habilitée.' USING ERRCODE='23514';END IF;
   IF NEW."ID_ResultatVerificationFk" NOT IN((parent."CircuitSnapshot"->'verification'->>'accepted')::integer,(parent."CircuitSnapshot"->'verification'->>'rejected')::integer) OR NEW."ID_ResultatVerificationFk" IS NULL THEN RAISE EXCEPTION 'Résultat absent du circuit du dossier.' USING ERRCODE='23514';END IF;
   IF nullif(btrim(NEW."CommentaireVerification"),'') IS NULL THEN RAISE EXCEPTION 'Commentaire de vérification obligatoire.' USING ERRCODE='23514';END IF;
   NEW."ID_VerifieParFk":=actor;NEW."DateVerification":=clock_timestamp();
  END IF;
 ELSE
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Le rattachement documentaire est immuable.' USING ERRCODE='23514';END IF;
  IF state='closed' THEN RAISE EXCEPTION 'Rouvrez le dossier avant ajout de preuve.' USING ERRCODE='23514';END IF;
  SELECT * INTO piece FROM logistique."T_PieceJustificative" WHERE "ID_Piece"=NEW."ID_PieceFk";
  IF piece."TypeObjet" IS DISTINCT FROM 'support' OR piece."ID_Objet" IS DISTINCT FROM NEW."ID_SupportFk" OR piece."IdEntiteFk" IS DISTINCT FROM parent."IdEntiteFk" THEN RAISE EXCEPTION 'Preuve liée à un autre dossier ou une autre entreprise.' USING ERRCODE='23514';END IF;
  IF NEW."ID_CommentaireSupportFk" IS NOT NULL AND NOT EXISTS(SELECT FROM support."T_CommentaireSupport" WHERE "ID_CommentaireSupport"=NEW."ID_CommentaireSupportFk" AND "ID_SupportFk"=parent."ID_Support" AND ("Visibilite"='public' OR NEW."Visibilite"='interne')) THEN RAISE EXCEPTION 'Commentaire de preuve incompatible avec le dossier ou sa visibilité.' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_enfant_support_verifier(); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.tr_enfant_support_verifier() IS 'Verrouille le parent puis valide les échanges, les tentatives successives et les liaisons documentaires ; aucune confusion entre identifiant de tiers et compte, aucune preuve interentreprise, vérification par un auteur distinct.';


--
-- Name: tr_lien_proprietaire_conserver(); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.tr_lien_proprietaire_conserver() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE old_id bigint;col text;
BEGIN
 IF NEW."IdEntiteFk" IS NOT DISTINCT FROM OLD."IdEntiteFk" THEN RETURN NEW;END IF;
 CASE TG_TABLE_NAME
 WHEN 'T_Client' THEN old_id:=OLD."ID_Client";col:='ID_DemandeurFk';
 WHEN 'T_Immobilisation' THEN old_id:=OLD."ID_Immobilisation";col:='ID_ImmobilisationFk';
 WHEN 'T_Commande' THEN old_id:=OLD."ID_Commande";col:='ID_CommandeFk';
 WHEN 'T_Article' THEN old_id:=OLD."ID_Article";col:='ID_ArticleFk';
 WHEN 'T_Utilisateurs' THEN
  IF EXISTS(SELECT FROM support."T_Support" WHERE "ID_ResponsableFk"=OLD."IdUser") THEN RAISE EXCEPTION 'Utilisateur affecté à un dossier Support ; entreprise conservée.' USING ERRCODE='23514';END IF;RETURN NEW;
 ELSE RAISE EXCEPTION 'Lien métier non pris en charge.';
 END CASE;
 IF EXISTS(SELECT FROM support."T_Support" s WHERE (to_jsonb(s)->>col)::bigint=old_id) THEN RAISE EXCEPTION 'Objet lié à un dossier Support ; entreprise conservée.' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION tr_lien_proprietaire_conserver(); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.tr_lien_proprietaire_conserver() IS 'Empêche le déplacement interentreprise d’un tiers, article, bon, matériel ou affectataire déjà lié à un dossier, actif ou archivé ; complète les contrôles lors du rattachement.';


--
-- Name: tr_piece_liaison_complete(); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.tr_piece_liaison_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW."TypeObjet"='support' AND EXISTS(SELECT FROM logistique."T_PieceJustificative" WHERE "ID_Piece"=NEW."ID_Piece") AND NOT EXISTS(SELECT FROM support."T_PieceSupport" WHERE "ID_PieceFk"=NEW."ID_Piece" AND "ID_SupportFk"=NEW."ID_Objet") THEN RAISE EXCEPTION 'Une preuve Support exige sa liaison métier dans la même transaction.' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $$;


--
-- Name: FUNCTION tr_piece_liaison_complete(); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.tr_piece_liaison_complete() IS 'Contrainte différée : un fichier Support du stockage commun possède sa liaison FK de dossier avant commit ; aucune preuve orpheline publiée.';


--
-- Name: tr_support_audit(); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.tr_support_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE before_data jsonb;after_data jsonb:=to_jsonb(NEW);ctx jsonb;parent_id bigint;entity_id integer;actor integer:=systeme.fn_admin_actor_user_id();
BEGIN
 IF TG_OP='UPDATE' THEN before_data:=to_jsonb(OLD);END IF;
 BEGIN ctx:=coalesce(nullif(current_setting('support.mutation',true),'')::jsonb,'{}'::jsonb);EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Contexte d’audit invalide.' USING ERRCODE='23514';END;
 IF ctx<>'{}'::jsonb AND (coalesce(ctx->>'requestId','') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR coalesce(ctx->>'payloadHash','') !~ '^[a-f0-9]{64}$' OR length(coalesce(ctx->>'motif',''))>2000) THEN RAISE EXCEPTION 'Preuve de requête invalide.' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME='T_Support' THEN parent_id:=NEW."ID_Support";entity_id:=NEW."IdEntiteFk";
 ELSE parent_id:=NEW."ID_SupportFk";SELECT "IdEntiteFk" INTO entity_id FROM support."T_Support" WHERE "ID_Support"=parent_id;END IF;
 after_data:=systeme.fn_audit_sans_secrets(after_data)||jsonb_build_object('_actor',jsonb_build_object('IdUser',actor),'ID_SupportFk',parent_id,'requestId',ctx->>'requestId','payloadHash',ctx->>'payloadHash','operation',coalesce(ctx->>'operation',lower(TG_OP)),'_motif',ctx->>'motif');
 INSERT INTO systeme."T_Audit_Log"("TableName","Operation","OldData","NewData","ChangedAt","IdEntiteFk") VALUES('support.'||TG_TABLE_NAME,coalesce(ctx->>'operation',TG_OP),systeme.fn_audit_sans_secrets(before_data),after_data,CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Kinshasa',entity_id);
 RETURN NULL;
END $_$;


--
-- Name: FUNCTION tr_support_audit(); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.tr_support_audit() IS 'Réutilise le journal système pour une image par écriture métier, acteur, entreprise, motif et preuve UUID/hash, dans la même transaction ; aucun contenu binaire n’est dupliqué.';


--
-- Name: tr_support_verifier(); Type: FUNCTION; Schema: support; Owner: -
--

CREATE FUNCTION support.tr_support_verifier() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE actor integer:=systeme.fn_admin_actor_user_id();actor_entity integer;actor_global boolean;old_state text;new_state text;cfg jsonb;ctx jsonb;reason text;f record;latest support."T_ResolutionSupport";target_entity integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Archivez le dossier pour conserver son historique.' USING ERRCODE='23514';END IF;
 IF actor IS NULL THEN RAISE EXCEPTION 'Auteur actif requis.' USING ERRCODE='23514';END IF;
 SELECT "IdEntiteFk","Is_Admin" INTO actor_entity,actor_global FROM systeme."T_Utilisateurs" WHERE "IdUser"=actor;
 IF NOT actor_global AND actor_entity IS DISTINCT FROM NEW."IdEntiteFk" THEN RAISE EXCEPTION 'Dossier hors entreprise de l’auteur.' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT FROM systeme."T_Entite" WHERE "IdEntite"=NEW."IdEntiteFk" AND "ValideEntite") THEN RAISE EXCEPTION 'Entreprise active requise.' USING ERRCODE='23514';END IF;
 BEGIN ctx:=coalesce(nullif(current_setting('support.mutation',true),'')::jsonb,'{}'::jsonb);EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'Contexte de traitement invalide.' USING ERRCODE='23514';END;
 reason:=nullif(btrim(ctx->>'motif'),'');
 IF TG_OP='INSERT' THEN
  NEW."NumeroSupport":='SUP-'||NEW."ID_Support"::text;NEW."ID_CreateurFk":=actor;NEW."CircuitSnapshot":=systeme.fn_support_circuit(NEW."IdEntiteFk");
  NEW."ID_StatutFk":=(NEW."CircuitSnapshot"->'states'->>'new')::integer;NEW."VersionEnregistrement":=1;
  NEW."DateCreation":=clock_timestamp();NEW."DateResolution":=NULL;NEW."DateCloture":=NULL;NEW."Archive":=false;
  -- Vérifier la configuration au moment de son utilisation, même si modifiée avant installation du garde.
  FOR f IN SELECT * FROM jsonb_each_text(NEW."CircuitSnapshot"->'states') LOOP
   IF f.value !~ '^[1-9][0-9]{0,8}$' OR NOT referentiel.fn_valider_reference_champ('support','T_Support','ID_StatutFk',f.value::integer,NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Le circuit ne correspond plus aux statuts configurés.' USING ERRCODE='23514';END IF;
  END LOOP;
 ELSE
  IF ROW(NEW."ID_Support",NEW."IdEntiteFk",NEW."NumeroSupport",NEW."ID_CreateurFk",NEW."DateCreation",NEW."CircuitSnapshot") IS DISTINCT FROM ROW(OLD."ID_Support",OLD."IdEntiteFk",OLD."NumeroSupport",OLD."ID_CreateurFk",OLD."DateCreation",OLD."CircuitSnapshot") THEN RAISE EXCEPTION 'Identité, propriétaire et circuit initial du dossier immuables.' USING ERRCODE='23514';END IF;
  IF NEW."VersionEnregistrement"<>OLD."VersionEnregistrement" THEN RAISE EXCEPTION 'La révision est attribuée par la base.' USING ERRCODE='23514';END IF;
  NEW."VersionEnregistrement":=OLD."VersionEnregistrement"+1;
  old_state:=support.fn_etat_support(OLD."CircuitSnapshot",OLD."ID_StatutFk");
  IF OLD."Archive" AND NEW."Archive" THEN RAISE EXCEPTION 'Restaurez le dossier avant modification.' USING ERRCODE='23514';END IF;
  IF NOT OLD."Archive" AND NEW."Archive" AND old_state<>'closed' THEN RAISE EXCEPTION 'Seul un dossier clôturé peut être archivé.' USING ERRCODE='23514';END IF;
  IF OLD."Archive" IS DISTINCT FROM NEW."Archive" AND reason IS NULL THEN RAISE EXCEPTION 'Motif d’archivage ou de restauration obligatoire.' USING ERRCODE='23514';END IF;
  IF OLD."Archive" IS DISTINCT FROM NEW."Archive" AND (to_jsonb(NEW)-ARRAY['Archive','VersionEnregistrement','DateModification']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['Archive','VersionEnregistrement','DateModification']) THEN RAISE EXCEPTION 'Archivage et modification se font séparément.' USING ERRCODE='23514';END IF;
 END IF;
 NEW."DateModification":=clock_timestamp();
 new_state:=support.fn_etat_support(NEW."CircuitSnapshot",NEW."ID_StatutFk");
 IF new_state IS NULL THEN RAISE EXCEPTION 'Statut absent du circuit du dossier.' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' AND NEW."ID_StatutFk" IS DISTINCT FROM OLD."ID_StatutFk" THEN
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(NEW."CircuitSnapshot"->'transitions') e WHERE e->>'from'=old_state AND e->>'to'=new_state) THEN RAISE EXCEPTION 'Transition non autorisée par le circuit du dossier.' USING ERRCODE='23514';END IF;
  IF (new_state='pending' OR (old_state IN('resolved','closed') AND new_state='active')) AND reason IS NULL THEN RAISE EXCEPTION 'Un motif est obligatoire pour la mise en attente ou la réouverture.' USING ERRCODE='23514';END IF;
  IF new_state IN('active','pending','resolved') AND NEW."ID_ResponsableFk" IS NULL THEN RAISE EXCEPTION 'Responsable requis avant prise en charge.' USING ERRCODE='23514';END IF;
  SELECT * INTO latest FROM support."T_ResolutionSupport" WHERE "ID_SupportFk"=NEW."ID_Support" ORDER BY "ID_ResolutionSupport" DESC LIMIT 1;
  IF new_state='resolved' THEN
   IF latest."ID_ResolutionSupport" IS NULL OR latest."ID_ResultatVerificationFk" IS NOT NULL OR latest."DateProposition"<OLD."DateModification" THEN RAISE EXCEPTION 'Nouvelle solution documentée requise avant résolution.' USING ERRCODE='23514';END IF;
   NEW."DateResolution":=clock_timestamp();NEW."DateCloture":=NULL;
  ELSIF new_state='closed' THEN
   IF old_state<>'resolved' OR latest."ID_ResultatVerificationFk" IS DISTINCT FROM (NEW."CircuitSnapshot"->'verification'->>'accepted')::integer OR latest."ID_VerifieParFk" IS NULL OR latest."ID_VerifieParFk"=latest."ID_ProposeParFk" THEN RAISE EXCEPTION 'Résolution vérifiée conforme par un autre responsable requise avant clôture.' USING ERRCODE='23514';END IF;
   NEW."DateCloture":=clock_timestamp();
  ELSIF old_state IN('resolved','closed') THEN NEW."DateCloture":=NULL;NEW."DateResolution":=NULL;
  END IF;
 ELSIF TG_OP='UPDATE' THEN NEW."DateResolution":=OLD."DateResolution";NEW."DateCloture":=OLD."DateCloture";
 END IF;
 IF TG_OP='UPDATE' AND old_state='closed' AND new_state='closed' AND NEW."Archive"=OLD."Archive" THEN RAISE EXCEPTION 'Rouvrez le dossier avant modification.' USING ERRCODE='23514';END IF;
 IF NEW."ID_ResponsableFk" IS NOT NULL THEN PERFORM 1 FROM systeme."T_Utilisateurs" WHERE "IdUser"=NEW."ID_ResponsableFk" FOR SHARE;END IF;
 IF NEW."ID_DemandeurFk" IS NOT NULL THEN PERFORM 1 FROM logistique."T_Client" WHERE "ID_Client"=NEW."ID_DemandeurFk" FOR SHARE;END IF;
 IF NEW."ID_ImmobilisationFk" IS NOT NULL THEN PERFORM 1 FROM logistique."T_Immobilisation" WHERE "ID_Immobilisation"=NEW."ID_ImmobilisationFk" FOR SHARE;END IF;
 IF NEW."ID_CommandeFk" IS NOT NULL THEN PERFORM 1 FROM logistique."T_Commande" WHERE "ID_Commande"=NEW."ID_CommandeFk" FOR SHARE;END IF;
 IF NEW."ID_ArticleFk" IS NOT NULL THEN PERFORM 1 FROM logistique."T_Article" WHERE "ID_Article"=NEW."ID_ArticleFk" FOR SHARE;END IF;
 IF NEW."ID_ResponsableFk" IS NOT NULL AND (TG_OP='INSERT' OR NEW."ID_ResponsableFk" IS DISTINCT FROM OLD."ID_ResponsableFk") AND NOT EXISTS(SELECT FROM systeme."T_Utilisateurs" WHERE "IdUser"=NEW."ID_ResponsableFk" AND "ValideUser" AND ("IdEntiteFk"=NEW."IdEntiteFk" OR "Is_Admin")) THEN RAISE EXCEPTION 'Responsable actif hors entreprise.' USING ERRCODE='23514';END IF;
 IF new_state IN('active','pending','resolved') AND NEW."ID_ResponsableFk" IS NULL THEN RAISE EXCEPTION 'Responsable requis pendant le traitement.' USING ERRCODE='23514';END IF;
 IF NEW."ID_DemandeurFk" IS NOT NULL AND NOT EXISTS(SELECT FROM logistique."T_Client" WHERE "ID_Client"=NEW."ID_DemandeurFk" AND "IdEntiteFk"=NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Demandeur hors entreprise.' USING ERRCODE='23514';END IF;
 IF NEW."ID_ImmobilisationFk" IS NOT NULL AND NOT EXISTS(SELECT FROM logistique."T_Immobilisation" WHERE "ID_Immobilisation"=NEW."ID_ImmobilisationFk" AND "IdEntiteFk"=NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Matériel hors entreprise.' USING ERRCODE='23514';END IF;
 IF NEW."ID_CommandeFk" IS NOT NULL AND NOT EXISTS(SELECT FROM logistique."T_Commande" WHERE "ID_Commande"=NEW."ID_CommandeFk" AND "IdEntiteFk"=NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Bon hors entreprise.' USING ERRCODE='23514';END IF;
 IF NEW."ID_ArticleFk" IS NOT NULL AND NOT EXISTS(SELECT FROM logistique."T_Article" WHERE "ID_Article"=NEW."ID_ArticleFk" AND "IdEntiteFk"=NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Article hors entreprise.' USING ERRCODE='23514';END IF;
 FOR f IN SELECT * FROM referentiel."T_ChampReferentiel" WHERE "SchemaName"='support' AND "TableName"='T_Support' AND "ColumnName"<>'ID_StatutFk' LOOP
  IF TG_OP='UPDATE' AND to_jsonb(NEW)->f."ColumnName" IS NOT DISTINCT FROM to_jsonb(OLD)->f."ColumnName" THEN CONTINUE;END IF;
  IF to_jsonb(NEW)->>f."ColumnName" IS NOT NULL THEN PERFORM 1 FROM referentiel."T_Generique" WHERE "ID_Generique"=(to_jsonb(NEW)->>f."ColumnName")::integer FOR SHARE;END IF;
  IF NOT referentiel.fn_valider_reference_champ('support','T_Support',f."ColumnName",(to_jsonb(NEW)->>f."ColumnName")::integer,NEW."IdEntiteFk") THEN RAISE EXCEPTION 'Référence inactive ou incompatible : %.',f."ColumnName" USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN NEW;
END $_$;


--
-- Name: FUNCTION tr_support_verifier(); Type: COMMENT; Schema: support; Owner: -
--

COMMENT ON FUNCTION support.tr_support_verifier() IS 'Socle métier SQL : propriété et identité immuables, copie initiale du circuit, références dynamiques, cohérence d’entreprise, responsable obligatoire, motif, solution puis vérification distincte avant clôture ; révision et dates exclusivement attribuées par la base.';


--
-- Name: audit_log_function(); Type: FUNCTION; Schema: systeme; Owner: -
--

CREATE FUNCTION systeme.audit_log_function() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE before_row jsonb; after_row jsonb; entity_id integer;
BEGIN
 IF TG_OP IN ('DELETE','UPDATE') THEN before_row:=systeme.fn_audit_sans_secrets(to_jsonb(OLD)); END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN after_row:=systeme.fn_audit_sans_secrets(to_jsonb(NEW)); END IF;
 entity_id:=coalesce((after_row->>'IdEntiteFk')::integer,(before_row->>'IdEntiteFk')::integer);
 INSERT INTO systeme."T_Audit_Log"("TableName","Operation","OldData","NewData","ChangedAt","IdEntiteFk")
 VALUES(TG_TABLE_NAME,TG_OP,before_row,after_row,current_timestamp,entity_id);
 RETURN NULL;
END;$$;


--
-- Name: FUNCTION audit_log_function(); Type: COMMENT; Schema: systeme; Owner: -
--

COMMENT ON FUNCTION systeme.audit_log_function() IS 'Audit AFTER INSERT/UPDATE/DELETE transactionnel : lit le contexte par JSON sans supposer une colonne IdEntiteFk, ne recopie ni mots de passe ni jetons et accepte une entité absente.';


--
-- Name: fn_admin_actor_user_id(); Type: FUNCTION; Schema: systeme; Owner: -
--

CREATE FUNCTION systeme.fn_admin_actor_user_id() RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $_$
DECLARE v_raw text:=nullif(current_setting('systeme.actor_user_id',true),''); v_id integer;
BEGIN
 IF v_raw IS NULL OR v_raw !~ '^[1-9][0-9]{0,9}$' THEN RETURN NULL; END IF;
 BEGIN v_id:=v_raw::integer;
 EXCEPTION WHEN numeric_value_out_of_range THEN RETURN NULL; END;
 IF EXISTS (SELECT 1 FROM systeme."T_Utilisateurs"
            WHERE "IdUser"=v_id AND "ValideUser" IS TRUE) THEN RETURN v_id; END IF;
 RETURN NULL;
END $_$;


--
-- Name: FUNCTION fn_admin_actor_user_id(); Type: COMMENT; Schema: systeme; Owner: -
--

COMMENT ON FUNCTION systeme.fn_admin_actor_user_id() IS 'Auteur actif existant de la GUC transactionnelle systeme.actor_user_id ; NULL si absence ou valeur invalide. Métadonnée de traçabilité, jamais autorisation SQL.';


--
-- Name: fn_admin_cle_sensible(text); Type: FUNCTION; Schema: systeme; Owner: -
--

CREATE FUNCTION systeme.fn_admin_cle_sensible(p_cle text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
 SELECT CASE WHEN p_cle IS NULL THEN false ELSE
  regexp_replace(lower(p_cle),'[^a-z0-9]','','g') ~
  '(password|motdepasse|privatekey|apikey|accesstoken|refreshtoken|idtoken|secret$)'
  OR regexp_replace(lower(p_cle),'[^a-z0-9]','','g') IN
   ('token','authorization','credential','credentials') END;
$_$;


--
-- Name: FUNCTION fn_admin_cle_sensible(p_cle text); Type: COMMENT; Schema: systeme; Owner: -
--

COMMENT ON FUNCTION systeme.fn_admin_cle_sensible(p_cle text) IS 'Détecte les noms de mots de passe, jetons et secrets sans dépendre de la casse ni des séparateurs.';


--
-- Name: fn_admin_reglage_audit(); Type: FUNCTION; Schema: systeme; Owner: -
--

CREATE FUNCTION systeme.fn_admin_reglage_audit() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE v_before jsonb; v_after jsonb; v_actor integer:=systeme.fn_admin_actor_user_id();
        v_identity jsonb:=jsonb_build_object('IdUser',NULL,'NomComplet',NULL);
        v_scope text; v_scope_value text; v_entity integer;
BEGIN
 IF v_actor IS NOT NULL THEN
  SELECT jsonb_build_object('IdUser',"IdUser",'NomComplet',
         concat_ws(' ',"PrenomUser","NomUser")) INTO v_identity
   FROM systeme."T_Utilisateurs" WHERE "IdUser"=v_actor;
 END IF;
 IF TG_OP IN ('DELETE','UPDATE') THEN
  v_before:=systeme.fn_audit_sans_secrets(to_jsonb(OLD));
  IF v_identity IS NOT NULL THEN v_before:=v_before||jsonb_build_object('_actor',v_identity); END IF;
 END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN
  v_after:=systeme.fn_audit_sans_secrets(to_jsonb(NEW));
  IF v_identity IS NOT NULL THEN v_after:=v_after||jsonb_build_object('_actor',v_identity); END IF;
 END IF;
 v_scope:=coalesce(v_after->>'SettingScope',v_before->>'SettingScope');
 v_scope_value:=coalesce(v_after->>'ScopeValue',v_before->>'ScopeValue');
 IF v_scope IN ('entity','entite') AND v_scope_value ~ '^[1-9][0-9]{0,9}$' THEN
  BEGIN v_entity:=v_scope_value::integer;
  EXCEPTION WHEN numeric_value_out_of_range THEN v_entity:=NULL; END;
  IF NOT EXISTS(SELECT 1 FROM systeme."T_Entite" WHERE "IdEntite"=v_entity) THEN v_entity:=NULL; END IF;
 END IF;
 INSERT INTO systeme."T_Audit_Log"("TableName","Operation","OldData","NewData","ChangedAt","IdEntiteFk")
 VALUES(TG_TABLE_NAME,TG_OP,v_before,v_after,CURRENT_TIMESTAMP AT TIME ZONE 'Africa/Kinshasa',v_entity);
 RETURN NULL;
END $_$;


--
-- Name: FUNCTION fn_admin_reglage_audit(); Type: COMMENT; Schema: systeme; Owner: -
--

COMMENT ON FUNCTION systeme.fn_admin_reglage_audit() IS 'Un événement SQL par écriture de réglage ou correspondance, avec images nettoyées et auteur de l’opération, y compris suppression.';


--
-- Name: fn_admin_ui_setting_proteger(); Type: FUNCTION; Schema: systeme; Owner: -
--

CREATE FUNCTION systeme.fn_admin_ui_setting_proteger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD."IsEditable" IS NOT TRUE OR OLD."IsSystem" IS TRUE THEN
   RAISE EXCEPTION 'Ce paramètre ne peut pas être supprimé' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD."IsEditable" IS NOT TRUE AND
  (to_jsonb(NEW)-ARRAY['UpdatedAt','UpdatedByUserFk']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['UpdatedAt','UpdatedByUserFk']) THEN
  RAISE EXCEPTION 'Ce paramètre est protégé contre les modifications' USING ERRCODE='23514';
 END IF;
 IF OLD."IsSystem" IS TRUE AND
  ROW(NEW."IdAdminUISetting",NEW."SettingKey",NEW."SettingType",NEW."SettingScope",
      NEW."ScopeValue",NEW."IsEditable",NEW."IsSystem",NEW."CreatedAt") IS DISTINCT FROM
  ROW(OLD."IdAdminUISetting",OLD."SettingKey",OLD."SettingType",OLD."SettingScope",
      OLD."ScopeValue",OLD."IsEditable",OLD."IsSystem",OLD."CreatedAt") THEN
  RAISE EXCEPTION 'Identité et protections du paramètre système immuables' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: FUNCTION fn_admin_ui_setting_proteger(); Type: COMMENT; Schema: systeme; Owner: -
--

COMMENT ON FUNCTION systeme.fn_admin_ui_setting_proteger() IS 'Refuse les modifications d’un paramètre non éditable et la suppression/altération d’identité d’un paramètre système ; sa valeur reste modifiable si IsEditable=true.';


