CREATE VIEW geolocalisation."V_Niveau_0" AS
 SELECT "ID_Niveau_0",
    "NomNiveau_0",
    iso,
    "CodeNiveau_0",
    "geometryNiveau_0",
    "uidSNIS",
    ( SELECT count(*) AS count
           FROM geolocalisation."T_Niveau_1" child
          WHERE (child."ID_Niveau_0_Fk" = n0."ID_Niveau_0")) AS "Nb_Niveau_1"
   FROM geolocalisation."T_Niveau_0" n0;


