          historique."TypeCmd",
          historique."SigneCommande",
          historique."EstCommandeEntree",
          historique."EstCommandeSortie",
          historique."AbrStatutCmd",
          historique."StatutCmd",
          historique."NomUser",
          historique."PrenomUser",
          historique."NomComplet",
