--
-- Name: T_LicenceModule; Type: TABLE; Schema: systeme; Owner: -
--

CREATE TABLE systeme."T_LicenceModule" (
    "IdLicenceModule" integer NOT NULL,
    "IdLicenceFk" integer NOT NULL,
    "CodeModule" character varying(32) NOT NULL,
