    a."Operation",
    a."ChangedAt",
    e."NomEntite",
    systeme.fn_audit_sans_secrets(a."OldData") AS "OldData",
    systeme.fn_audit_sans_secrets(a."NewData") AS "NewData"
   FROM (systeme."T_Audit_Log" a
     LEFT JOIN systeme."T_Entite" e ON ((e."IdEntite" = a."IdEntiteFk")));


